MATCH (:PlantItem {tag: 'EA-301'})-[:is_drawn_on]->(s:Sheet)
RETURN s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (:PlantItem {tag: 'K-1201'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'HS-6003'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(:PlantItem {tag: 'P-301B'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'V-1101'}), (b:PlantItem {tag: 'E-1101'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag
LIMITATIONS: NONE

MATCH (a:PlantItem {tag: 'V-1101'}), (b:PlantItem {tag: 'E-1101'}), (v:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(tank:PlantItem {tag: 'TK-104'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:BallValve {unit_id: '5'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(i:PlantItem {loop_tag: 'PI-12047'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'H-1101'}), (b:PlantItem {tag: 'E-1101'}), (v:PlantItem {tag: 'V-1101'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE all(n IN nodes(p) WHERE n <> v)
       } AS reachable_final

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem), (s)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'PIC-12034'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'P-302A'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'F-1701B'}), (b:PlantItem {tag: 'TK-1801'}), (c:PlantItem)
WHERE EXISTS { (a)-[:send_to*1..]->(c) }
  AND EXISTS { (b)-[:send_to*1..]->(c) }
  AND NOT EXISTS {
    MATCH (d:PlantItem)
    WHERE d <> c
      AND EXISTS { (a)-[:send_to*1..]->(d) }
      AND EXISTS { (b)-[:send_to*1..]->(d) }
      AND EXISTS { (d)-[:send_to*1..]->(c) }
  }
RETURN DISTINCT c.tag AS tag ORDER BY tag

MATCH (loop:ProcessInstrumentationFunction:PlantItem {loop_tag: 'LSHH-6004'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'T-501'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:Valve)-[:line_to*1..]->(tank:PlantItem {tag: 'TK-101'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-1301B'}), (b:PlantItem {tag: 'P-1302A'}), (v:PlantItem:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-1601B'}), (b:PlantItem {tag: 'P-1801'}), (c:PlantItem)
WHERE EXISTS { (a)-[:line_to*1..]->(c) }
  AND EXISTS { (b)-[:line_to*1..]->(c) }
  AND NOT EXISTS {
    MATCH (x:PlantItem)
    WHERE EXISTS { (a)-[:line_to*1..]->(x) }
      AND EXISTS { (b)-[:line_to*1..]->(x) }
      AND EXISTS { (x)-[:line_to*1..]->(c) }
  }
RETURN DISTINCT c.tag AS tag
ORDER BY tag

MATCH (t:PlantItem {tag: 'TK-602'})-[:line_to]-(v:Valve)<-[:control]-(a:ActuatingFunction)<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-1601'}), (b:PlantItem {tag: 'TK-1603'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'V-1102'}), (b:PlantItem {tag: 'EJ-1302B'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-902'}), (b:PlantItem {tag: 'H-1101'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem WHERE y.tag <> 'GV-10001'))+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'P-1801'}), (b:PlantItem {tag: 'V-1501'}), (c:PlantItem)
WHERE EXISTS { (a)-[:line_to*1..]->(c) }
  AND EXISTS { (b)-[:line_to*1..]->(c) }
  AND NOT EXISTS {
    MATCH (d:PlantItem)
    WHERE d <> c
      AND EXISTS { (a)-[:line_to*1..]->(d) }
      AND EXISTS { (b)-[:line_to*1..]->(d) }
      AND EXISTS { (d)-[:line_to*1..]->(c) }
  }
RETURN DISTINCT c.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-1801'}), (b:PlantItem {tag: 'V-1501'})
CALL {
  WITH a
  MATCH (a)-[:line_to*1..]->(x:PlantItem)
  RETURN collect(DISTINCT x) AS downstreamA
}
CALL {
  WITH b
  MATCH (b)-[:line_to*1..]->(y:PlantItem)
  RETURN collect(DISTINCT y) AS downstreamB
}
WITH [x IN downstreamA WHERE x IN downstreamB] AS common
UNWIND common AS c
WHERE NOT EXISTS {
  UNWIND common AS d
  WITH c, d
  WHERE d <> c
    AND EXISTS { (d)-[:line_to*1..]->(c) }
}
RETURN DISTINCT c.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-302A'}), (b:PlantItem {tag: 'K-501'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-1301A'}), (b:PlantItem {tag: 'TK-1801'}), (c:PlantItem)
WHERE c <> a AND c <> b
  AND EXISTS { (a)-[:line_to*1..]->(c) }
  AND EXISTS { (b)-[:line_to*1..]->(c) }
  AND NOT EXISTS {
    MATCH (x:PlantItem)
    WHERE x <> c
      AND EXISTS { (a)-[:line_to*1..]->(x) }
      AND EXISTS { (b)-[:line_to*1..]->(x) }
      AND EXISTS { (x)-[:line_to*1..]->(c) }
  }
RETURN DISTINCT c.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-1301A'}), (b:PlantItem {tag: 'TK-1801'})
CALL {
  WITH a
  MATCH (a)-[:line_to*1..]->(n:PlantItem)
  RETURN collect(DISTINCT n) AS downstreamA
}
CALL {
  WITH b
  MATCH (b)-[:line_to*1..]->(n:PlantItem)
  RETURN collect(DISTINCT n) AS downstreamB
}
WITH [n IN downstreamA WHERE n IN downstreamB] AS common
UNWIND common AS c
WITH common, c
WHERE NOT EXISTS {
  UNWIND common AS x
  WITH x, c
  WHERE x <> c AND EXISTS { (x)-[:line_to*1..]->(c) }
}
RETURN DISTINCT c.tag AS tag
ORDER BY tag
